arguments.argument:
//Pull camera up animation
if pull = 0
and image_index > 10.2
{
    sprite_index = spr_cameraforeground
    image_speed = 0
    instance_create(x,y,obj_cameraglitch)
    sound_stop(snd_energy)
}
if pull = 1
and image_index < 0
    instance_destroy()
//Camera image horizontal movement
if move = 0
{
    offset -= 1
    if offset < -180
    {
        alarm[0] = 30
        move = 2
    }
}
if move = 1
{
    offset += 1
    if offset > 68
    {
        alarm[1] = 30
        move = 2
    }
}
interruptedimg += 1
if instance_exists(obj_powerout)
and sprite_index = spr_cameraforeground
{
    sprite_index = spr_camera
    image_index = 10.2
    image_speed = -1
    pull = 1
    sound_stop(snd_monitorup)
    sound_play(snd_monitordown)
    instance_activate_object(obj_torch)

}
